import os
import azure.cognitiveservices.speech as speechsdk

def get_speech_config():
    api_key = os.getenv('AZURE_SPEECH_KEY')
    region = os.getenv('AZURE_SPEECH_REGION')
    return speechsdk.SpeechConfig(subscription=api_key, region=region)

from typing import Any, Dict

def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'language_code': payload.get('language_code', 'en-US'),
        'sample_rate_hz': payload.get('sample_rate_hz', 16000),
        'audio_chunks': payload.get('audio_chunks', [])
    }

def parse_result(result: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'text': result.get('text', ''),
        'is_final': result.get('is_final', False)
    }

import requests

def translate_caption(caption, target_language):
    url = f'https://api.deepl.com/v2/translate?auth_key={os.getenv('DEEPL_API_KEY')}'
    data = {
        'text': caption,
        'target_lang': target_language
    }
    response = requests.post(url, data=data)
    response.raise_for_status()
    return response.json()['translations'][0]['text']

import requests

def check_safety(caption):
    url = f'https://api.perspectiveapi.com/v1alpha1/commentAnalyzer?key={os.getenv('PERSPECTIVE_API_KEY')}'
    data = {
        'comment': {'text': caption},
        'languages': ['en']
    }
    response = requests.post(url, json=data)
    response.raise_for_status()
    return response.json()['attributeScores']['TOXICITY']['summaryScore']['value'] < 0.5

import requests

def summarize_meeting(transcript):
    url = f'https://api.meaningcloud.com/summarization-1.0?key={os.getenv('MEANINGCLOUD_API_KEY')}'
    data = {
        'txt': transcript,
        'sentences': 5
    }
    response = requests.post(url, data=data)
    response.raise_for_status()
    return response.json()['summary']

import requests

def embed_caption(caption):
    url = f'https://api.sentence-transformers.com/v1/embeddings?api_key={os.getenv('SENTENCE_TRANSFORMERS_API_KEY')}'
    data = {
        'sentences': [caption]
    }
    response = requests.post(url, json=data)
    response.raise_for_status()
    return response.json()['data'][0]['embedding']
